// Build batches
// Splits the candidates into batches of blocklist_ai_batch_size. Each batch
// becomes one AI request: system message = active classifier prompt, user
// message = the domains as JSON. Domain names are untrusted data.
// Mode: Run Once for All Items.

const config = $('Load blocklist configuration').first().json;
const size = Math.min(100, Math.max(1, Math.trunc(Number(config.settings.blocklist_ai_batch_size) || 50)));
// No rows: the Postgres node may still emit one item without fqdn.
const rows = $input.all().map((i) => i.json).filter((r) => typeof r.fqdn === 'string' && r.fqdn);

const out = [];
for (let i = 0; i < rows.length; i += size) {
  const queue = rows.slice(i, i + size).map((r) => ({
    fqdn: r.fqdn,
    matched_pattern: r.matched_pattern,
    query_count: Number(r.query_count),
    client_count: Number(r.client_count),
  }));
  out.push({
    json: {
      batch_no: out.length + 1,
      system_message: config.system_prompt,
      user_message: JSON.stringify({ domains: queue }, null, 2),
      prompt_version: config.prompt_version,
      queue,
    },
  });
}
return out;

