// Validate classifications
// Keeps only answers about domains that were in the batch, with valid
// categories. A failed batch is stored as nothing: its domains stay in the
// queue and are sent again on the next run.
// Mode: Run Once for Each Item.

// Keep in sync with the model selected in the "Google Gemini Chat Model" node.
const AI_MODEL = 'gemini-3.1-flash-lite';
const CATEGORIES = ['telemetry', 'tracking', 'ads', 'functional', 'unknown'];
const LEVELS = ['low', 'medium', 'high'];

const batch = $('Build batches').all()[$itemIndex].json;
const ai = $json; // { output: {...} } | { text: '...' } | { error: ... }
const sent = new Set(batch.queue.map((q) => q.fqdn));

let results = [];
let aiError = null;
try {
  if (ai.error) throw new Error(typeof ai.error === 'string' ? ai.error : ai.error.message || JSON.stringify(ai.error));
  let out = ai.output ?? ai.text ?? ai.response?.text;
  if (typeof out === 'string') out = JSON.parse(out.replace(/^```(?:json)?\s*|\s*```$/g, ''));
  if (out && typeof out === 'object' && out.output && typeof out.output === 'object') out = out.output;
  if (!out || !Array.isArray(out.results)) throw new Error('classifier returned no "results" array');
  for (const r of out.results) {
    const fqdn = String(r?.fqdn ?? '').trim().toLowerCase().replace(/\.$/, '');
    const category = String(r?.category ?? '').trim().toLowerCase();
    const confidence = String(r?.confidence ?? '').trim().toLowerCase();
    const risk = String(r?.breakage_risk ?? '').trim().toLowerCase();
    if (!sent.has(fqdn) || !CATEGORIES.includes(category) || !LEVELS.includes(confidence) || !LEVELS.includes(risk)) continue;
    results.push({
      fqdn,
      category,
      vendor: String(r.vendor ?? '').replace(/\s+/g, ' ').trim().slice(0, 100),
      confidence,
      breakage_risk: risk,
      reason: String(r.reason ?? '').replace(/\s+/g, ' ').trim().slice(0, 500),
    });
  }
} catch (e) {
  aiError = String(e.message || e).slice(0, 500);
  results = [];
}

return {
  json: {
    batch_no: batch.batch_no,
    sent: batch.queue.length,
    answered: results.length,
    ai_error: aiError,
    results,
    queue: batch.queue,
    ai_model: AI_MODEL,
    prompt_version: batch.prompt_version,
  },
};

// Summarize run
// One item for the whole run: totals and failed batches.
// Mode: Run Once for All Items.

const stored = $input.all().map((i) => i.json.stored || {});
const batches = $('Validate classifications').all().map((i) => i.json);
const sum = (key) => stored.reduce((n, s) => n + Number(s[key] || 0), 0);
const pending = $('Load candidates').all().filter((i) => i.json.fqdn).length;

return [{
  json: {
    batches: batches.length,
    sent: sum('sent'),
    stored: sum('stored'),
    proposed: sum('proposed'),
    failed_batches: batches.filter((b) => b.ai_error).map((b) => ({ batch_no: b.batch_no, error: b.ai_error })),
    queue_loaded: pending,
  },
}];

// Build e-mail
// New telemetry / tracking candidates wait for review in the AI config UI.
// Mode: Run Once for Each Item.

const esc = (value) => String(value ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const s = $('Summarize run').first().json;
const failed = s.failed_batches.length
  ? `<p style="color:#ff5252;">${s.failed_batches.length} AI batch(es) failed — their domains are retried on the next run.<br>` +
    s.failed_batches.map((f) => `Batch ${esc(f.batch_no)}: ${esc(f.error)}`).join('<br>') + '</p>'
  : '';

return {
  json: {
    subject: `[Cyber Sentinel] Blocklists: ${s.proposed} new candidate(s) to review`,
    html: `<div style="font-family:Arial,sans-serif;background:#1e1e1e;color:#e0e0e0;padding:20px;">
<h2 style="margin:0 0 12px;">Own blocklists — review needed</h2>
<p>The AI classified ${esc(s.stored)} domain(s); <strong>${esc(s.proposed)}</strong> were proposed for the telemetry or tracking list.</p>
${failed}
<p>Approve or reject them on the <strong>Blocklists</strong> page of the AI config UI. Approved domains go into the next daily pull request to sentinel-blocklists.</p>
</div>`,
  },
};
